using Xunit;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Models;

public class PersonTests
{
    [Fact]
    public void FullName_ReturnsLastNameCommaFirstName()
    {
        // Arrange
        var student = new Student
        {
            LastName = "Smith",
            FirstMidName = "John",
            EnrollmentDate = DateTime.Today
        };

        // Act
        var fullName = student.FullName;

        // Assert
        Assert.Equal("Smith, John", fullName);
    }

    [Theory]
    [InlineData("Doe", "Jane", "Doe, Jane")]
    [InlineData("O'Brien", "Conan", "O'Brien, Conan")]
    [InlineData("X", "Y", "X, Y")]
    public void FullName_VariousNames_FormatsCorrectly(string lastName, string firstName, string expected)
    {
        var instructor = new Instructor
        {
            LastName = lastName,
            FirstMidName = firstName,
            HireDate = DateTime.Today
        };

        Assert.Equal(expected, instructor.FullName);
    }
}

public class StudentTests
{
    [Fact]
    public void Student_InheritsFromPerson()
    {
        var student = new Student();
        Assert.IsAssignableFrom<Person>(student);
    }

    [Fact]
    public void Student_Properties_SetAndGet()
    {
        var date = new DateTime(2023, 9, 1);
        var student = new Student
        {
            ID = 5,
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = date
        };

        Assert.Equal(5, student.ID);
        Assert.Equal("Test", student.LastName);
        Assert.Equal("User", student.FirstMidName);
        Assert.Equal(date, student.EnrollmentDate);
        Assert.Equal("Test, User", student.FullName);
    }
}

public class InstructorTests
{
    [Fact]
    public void Instructor_InheritsFromPerson()
    {
        var instructor = new Instructor();
        Assert.IsAssignableFrom<Person>(instructor);
    }

    [Fact]
    public void Instructor_Properties_SetAndGet()
    {
        var hireDate = new DateTime(2000, 3, 15);
        var instructor = new Instructor
        {
            ID = 3,
            LastName = "Prof",
            FirstMidName = "Teacher",
            HireDate = hireDate
        };

        Assert.Equal(3, instructor.ID);
        Assert.Equal("Prof", instructor.LastName);
        Assert.Equal("Teacher", instructor.FirstMidName);
        Assert.Equal(hireDate, instructor.HireDate);
    }

    [Fact]
    public void Instructor_CanHaveOfficeAssignment()
    {
        var instructor = new Instructor
        {
            ID = 1,
            LastName = "Test",
            FirstMidName = "Inst",
            HireDate = DateTime.Today,
            OfficeAssignment = new OfficeAssignment { InstructorID = 1, Location = "Room 101" }
        };

        Assert.NotNull(instructor.OfficeAssignment);
        Assert.Equal("Room 101", instructor.OfficeAssignment.Location);
    }
}

public class CourseTests
{
    [Fact]
    public void Course_Properties_SetAndGet()
    {
        var course = new Course
        {
            CourseID = 1050,
            Title = "Chemistry",
            Credits = 3,
            DepartmentID = 1,
            TeachingMaterialImagePath = "/images/chem.jpg"
        };

        Assert.Equal(1050, course.CourseID);
        Assert.Equal("Chemistry", course.Title);
        Assert.Equal(3, course.Credits);
        Assert.Equal(1, course.DepartmentID);
        Assert.Equal("/images/chem.jpg", course.TeachingMaterialImagePath);
    }
}

public class DepartmentTests
{
    [Fact]
    public void Department_Properties_SetAndGet()
    {
        var startDate = new DateTime(2007, 9, 1);
        var department = new Department
        {
            DepartmentID = 1,
            Name = "Engineering",
            Budget = 350000m,
            StartDate = startDate,
            InstructorID = 5
        };

        Assert.Equal(1, department.DepartmentID);
        Assert.Equal("Engineering", department.Name);
        Assert.Equal(350000m, department.Budget);
        Assert.Equal(startDate, department.StartDate);
        Assert.Equal(5, department.InstructorID);
    }

    [Fact]
    public void Department_InstructorID_CanBeNull()
    {
        var department = new Department
        {
            Name = "Empty",
            Budget = 0,
            StartDate = DateTime.Today,
            InstructorID = null
        };

        Assert.Null(department.InstructorID);
    }

    [Fact]
    public void Department_RowVersion_CanBeSet()
    {
        var dept = new Department();
        var rowVersion = new byte[] { 0x00, 0x01, 0x02 };
        dept.RowVersion = rowVersion;

        Assert.Equal(rowVersion, dept.RowVersion);
    }
}

public class EnrollmentTests
{
    [Theory]
    [InlineData(Grade.A)]
    [InlineData(Grade.B)]
    [InlineData(Grade.C)]
    [InlineData(Grade.D)]
    [InlineData(Grade.F)]
    public void Enrollment_Grade_AcceptsAllValues(Grade grade)
    {
        var enrollment = new Enrollment
        {
            EnrollmentID = 1,
            CourseID = 100,
            StudentID = 10,
            Grade = grade
        };

        Assert.Equal(grade, enrollment.Grade);
    }

    [Fact]
    public void Enrollment_Grade_CanBeNull()
    {
        var enrollment = new Enrollment
        {
            EnrollmentID = 2,
            CourseID = 100,
            StudentID = 10,
            Grade = null
        };

        Assert.Null(enrollment.Grade);
    }
}

public class NotificationModelTests
{
    [Fact]
    public void Notification_Properties_SetAndGet()
    {
        var createdAt = new DateTime(2024, 1, 15, 10, 30, 0);
        var readAt = new DateTime(2024, 1, 15, 11, 0, 0);

        var notification = new Notification
        {
            Id = 1,
            EntityType = "Student",
            EntityId = "42",
            Operation = "CREATE",
            Message = "New student created",
            CreatedAt = createdAt,
            CreatedBy = "Admin",
            IsRead = true,
            ReadAt = readAt
        };

        Assert.Equal(1, notification.Id);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("New student created", notification.Message);
        Assert.Equal(createdAt, notification.CreatedAt);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.True(notification.IsRead);
        Assert.Equal(readAt, notification.ReadAt);
    }

    [Fact]
    public void Notification_ReadAt_DefaultsToNull()
    {
        var notification = new Notification
        {
            EntityType = "Course",
            EntityId = "1",
            Operation = "UPDATE",
            Message = "Course updated",
            CreatedAt = DateTime.Now,
            IsRead = false
        };

        Assert.Null(notification.ReadAt);
        Assert.False(notification.IsRead);
    }
}

public class ErrorViewModelTests
{
    [Fact]
    public void ShowRequestId_WhenRequestIdIsSet_ReturnsTrue()
    {
        var model = new ErrorViewModel { RequestId = "abc-123" };
        Assert.True(model.ShowRequestId);
    }

    [Fact]
    public void ShowRequestId_WhenRequestIdIsNull_ReturnsFalse()
    {
        var model = new ErrorViewModel { RequestId = null };
        Assert.False(model.ShowRequestId);
    }

    [Fact]
    public void ShowRequestId_WhenRequestIdIsEmpty_ReturnsFalse()
    {
        var model = new ErrorViewModel { RequestId = "" };
        Assert.False(model.ShowRequestId);
    }
}

public class CourseAssignmentTests
{
    [Fact]
    public void CourseAssignment_Properties_SetAndGet()
    {
        var ca = new CourseAssignment
        {
            CourseID = 1050,
            InstructorID = 3
        };

        Assert.Equal(1050, ca.CourseID);
        Assert.Equal(3, ca.InstructorID);
    }
}

public class OfficeAssignmentTests
{
    [Fact]
    public void OfficeAssignment_Properties_SetAndGet()
    {
        var oa = new OfficeAssignment
        {
            InstructorID = 5,
            Location = "Room 301"
        };

        Assert.Equal(5, oa.InstructorID);
        Assert.Equal("Room 301", oa.Location);
    }
}

public class EntityOperationTests
{
    [Theory]
    [InlineData(EntityOperation.CREATE, "CREATE")]
    [InlineData(EntityOperation.UPDATE, "UPDATE")]
    [InlineData(EntityOperation.DELETE, "DELETE")]
    public void EntityOperation_ToString_ReturnsExpectedString(EntityOperation op, string expected)
    {
        Assert.Equal(expected, op.ToString());
    }
}

