using Xunit;
using ContosoUniversity.Services;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        _sut = new NotificationService();
        // Drain any leftover notifications from the static queue (shared across tests)
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        _sut.Dispose();
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_EnqueuesNotification()
    {
        // Act
        _sut.SendNotification("Student", "42", EntityOperation.CREATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("Student (ID: 42)", notification.Message);
        Assert.Contains("created", notification.Message);
        Assert.Equal("System", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithDisplayName_IncludesDisplayNameInMessage()
    {
        // Act
        _sut.SendNotification("Course", "101", "Advanced Math", EntityOperation.CREATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("Course 'Advanced Math'", notification.Message);
        Assert.Contains("created", notification.Message);
    }

    [Fact]
    public void SendNotification_WithUserName_SetsCreatedBy()
    {
        // Act
        _sut.SendNotification("Student", "1", EntityOperation.CREATE, "AdminUser");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("AdminUser", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_WithoutUserName_DefaultsToSystem()
    {
        // Act
        _sut.SendNotification("Student", "1", EntityOperation.UPDATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "created")]
    [InlineData(EntityOperation.UPDATE, "updated")]
    [InlineData(EntityOperation.DELETE, "deleted")]
    public void SendNotification_DifferentOperations_GeneratesCorrectMessage(
        EntityOperation operation, string expectedVerb)
    {
        // Act
        _sut.SendNotification("Department", "5", "Engineering", operation);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal(operation.ToString(), notification.Operation);
        Assert.Contains(expectedVerb, notification.Message);
        Assert.Contains("Engineering", notification.Message);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToNonDefault()
    {
        // Act
        var before = DateTime.Now.AddSeconds(-1);
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);
        var after = DateTime.Now.AddSeconds(1);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }

    [Fact]
    public void ReceiveNotification_WhenQueueEmpty_ReturnsNull()
    {
        // Act
        var result = _sut.ReceiveNotification();

        // Assert
        Assert.Null(result);
    }

    [Fact]
    public void ReceiveNotification_ReturnsFIFOOrder()
    {
        // Arrange
        _sut.SendNotification("A", "1", EntityOperation.CREATE);
        _sut.SendNotification("B", "2", EntityOperation.UPDATE);
        _sut.SendNotification("C", "3", EntityOperation.DELETE);

        // Act & Assert
        var first = _sut.ReceiveNotification();
        Assert.Equal("A", first!.EntityType);

        var second = _sut.ReceiveNotification();
        Assert.Equal("B", second!.EntityType);

        var third = _sut.ReceiveNotification();
        Assert.Equal("C", third!.EntityType);

        Assert.Null(_sut.ReceiveNotification());
    }

    [Fact]
    public void SendNotification_WithNullDisplayName_UsesIdFormat()
    {
        // Act
        _sut.SendNotification("Student", "99", null, EntityOperation.UPDATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("Student (ID: 99)", notification.Message);
        Assert.Contains("updated", notification.Message);
    }

    [Fact]
    public void SendNotification_WithEmptyDisplayName_UsesIdFormat()
    {
        // Act
        _sut.SendNotification("Course", "50", "  ", EntityOperation.DELETE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("Course (ID: 50)", notification.Message);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op in the in-memory implementation
        var exception = Record.Exception(() => _sut.MarkAsRead(42));
        Assert.Null(exception);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();
        var exception = Record.Exception(() => service.Dispose());
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_CreateOperation_MessageStartsWithNew()
    {
        _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.StartsWith("New ", notification.Message);
    }

    [Fact]
    public void SendNotification_UpdateOperation_DoesNotStartWithNew()
    {
        _sut.SendNotification("Student", "1", "John Doe", EntityOperation.UPDATE);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.DoesNotContain("New ", notification.Message);
        Assert.StartsWith("Student", notification.Message);
    }

    [Fact]
    public void SendNotification_DeleteOperation_MessageContainsDeleted()
    {
        _sut.SendNotification("Course", "100", "Physics", EntityOperation.DELETE);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Course 'Physics' has been deleted", notification.Message);
    }
}

