using Xunit;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Data;

public class DbInitializerTests
{
    [Fact]
    public void Initialize_EmptyDatabase_SeedsStudents()
    {
        // Arrange
        using var context = TestHelpers.CreateInMemoryContext();

        // Act
        DbInitializer.Initialize(context);

        // Assert
        Assert.Equal(8, context.Students.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsInstructors()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(5, context.Instructors.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsDepartments()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(4, context.Departments.Count());
        var english = context.Departments.Single(d => d.Name == "English");
        Assert.Equal(350000m, english.Budget);
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsCourses()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(7, context.Courses.Count());
        var chemistry = context.Courses.Single(c => c.Title == "Chemistry");
        Assert.Equal(1050, chemistry.CourseID);
        Assert.Equal(3, chemistry.Credits);
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsEnrollments()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(11, context.Enrollments.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsOfficeAssignments()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(3, context.OfficeAssignments.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsCourseAssignments()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(8, context.CourseAssignments.Count());
    }

    [Fact]
    public void Initialize_AlreadySeeded_DoesNotDuplicateData()
    {
        // Arrange
        using var context = TestHelpers.CreateInMemoryContext();
        DbInitializer.Initialize(context);
        var studentCount = context.Students.Count();

        // Act - Initialize again
        DbInitializer.Initialize(context);

        // Assert - counts should be unchanged
        Assert.Equal(studentCount, context.Students.Count());
    }

    [Fact]
    public void Initialize_SeedsStudentsWithCorrectData()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        var carson = context.Students.Single(s => s.LastName == "Alexander");
        Assert.Equal("Carson", carson.FirstMidName);
        Assert.Equal(new DateTime(2010, 9, 1), carson.EnrollmentDate);
    }

    [Fact]
    public void Initialize_DepartmentsHaveAdministrators()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        var departments = context.Departments.ToList();
        Assert.All(departments, d => Assert.NotNull(d.InstructorID));
    }

    [Fact]
    public void Initialize_EnrollmentsHaveGrades_ExceptSome()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        var enrollments = context.Enrollments.ToList();
        var withGrades = enrollments.Count(e => e.Grade.HasValue);
        var withoutGrades = enrollments.Count(e => !e.Grade.HasValue);
        Assert.True(withGrades > 0, "Should have enrollments with grades");
        Assert.True(withoutGrades > 0, "Should have enrollments without grades");
    }
}

