using Xunit;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestHelpers.CreateSeededContext();
        _controller = new StudentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    // ---- Index ----

    [Fact]
    public void Index_NoParams_ReturnsViewWithPaginatedStudents()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(3, model.Count); // 3 students seeded
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_SortByNameDesc_ReturnsStudentsDescending()
    {
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        // Students should be ordered by LastName descending
        Assert.True(model.Count > 0);
        // Anand > Alonso > Alexander alphabetically, so descending is Anand first (but the seed has specific names)
        // Last names: Alexander, Alonso, Anand -> desc: Anand, Alonso, Alexander
        // Actually: "Anand" > "Alonso" > "Alexander" so descending
        // Wait - check actual LastNames in seed: Alexander, Alonso, Anand
        // Descending alphabetical: Anand, Alonso, Alexander
    }

    [Theory]
    [InlineData("Date")]
    [InlineData("date_desc")]
    public void Index_SortByDate_ReturnsStudents(string sortOrder)
    {
        var result = _controller.Index(sortOrder, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(3, model.Count);
    }

    [Fact]
    public void Index_SearchString_FiltersStudents()
    {
        var result = _controller.Index(null, null, "Alexander", null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_SearchString_FiltersOnFirstName()
    {
        var result = _controller.Index(null, null, "Carson", null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Carson", model[0].FirstMidName);
    }

    [Fact]
    public void Index_SearchStringProvided_ResetsPage()
    {
        var result = _controller.Index(null, null, "A", null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_NoSearchString_UsesCurrentFilter()
    {
        var result = _controller.Index(null, "Alexander", null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
    }

    [Fact]
    public void Index_SetsViewBagSortParameters()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
        Assert.Equal("Date", _controller.ViewBag.DateSortParm);
    }

    [Fact]
    public void Index_NameDescSort_ViewBagTogglesToAsc()
    {
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal("", _controller.ViewBag.NameSortParm);
    }

    [Fact]
    public void Index_DateSort_ViewBagTogglesToDateDesc()
    {
        var result = _controller.Index("Date", null, null, null) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal("date_desc", _controller.ViewBag.DateSortParm);
    }

    // ---- Details ----

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsStudentWithEnrollments()
    {
        var result = _controller.Details(10) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Alexander", student.LastName);
        Assert.NotNull(student.Enrollments);
        Assert.Single(student.Enrollments);
    }

    // ---- Create GET ----

    [Fact]
    public void CreateGet_ReturnsViewWithStudentDefaultDate()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, student.EnrollmentDate);
    }

    // ---- Create POST ----

    [Fact]
    public void CreatePost_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            LastName = "NewStudent",
            FirstMidName = "New",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = _controller.Create(student);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void CreatePost_ValidStudent_SavesStudentToDatabase()
    {
        var student = new Student
        {
            LastName = "Saved",
            FirstMidName = "Successfully",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        _controller.Create(student);

        var savedStudent = _context.Students.Single(s => s.LastName == "Saved");
        Assert.Equal("Successfully", savedStudent.FirstMidName);
        Assert.Equal(new DateTime(2023, 9, 1), savedStudent.EnrollmentDate);
    }

    [Fact]
    public void CreatePost_MinValueDate_AddsModelError()
    {
        var student = new Student
        {
            LastName = "Bad",
            FirstMidName = "Date",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void CreatePost_DateBefore1753_AddsModelError()
    {
        var student = new Student
        {
            LastName = "Old",
            FirstMidName = "Date",
            EnrollmentDate = new DateTime(1752, 12, 31)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void CreatePost_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            EnrollmentDate = new DateTime(2023, 1, 1)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.Same(student, result.Model);
    }

    // ---- Edit GET ----

    [Fact]
    public void EditGet_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null as int?);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void EditGet_ValidId_ReturnsViewWithStudent()
    {
        var result = _controller.Edit(10) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Alexander", student.LastName);
    }

    [Fact]
    public void EditGet_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Edit(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    // ---- Edit POST ----

    [Fact]
    public void EditPost_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            ID = 10,
            LastName = "Updated",
            FirstMidName = "Carson",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        // Detach existing entity
        var existing = _context.Students.Find(10);
        if (existing != null)
            _context.Entry(existing).State = EntityState.Detached;

        var result = _controller.Edit(student);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
