    public void CreateGet_ReturnsViewWithNewInstructor()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        Assert.IsType<Instructor>(result.Model);
        Assert.NotNull(_controller.ViewBag.Courses);
    }

    [Fact]
    public void CreateGet_PopulatesAssignedCourseData()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var courses = Assert.IsAssignableFrom<IList<AssignedCourseData>>(_controller.ViewBag.Courses);
        Assert.Equal(2, courses.Count); // 2 courses seeded
        Assert.All(courses, c => Assert.False(c.Assigned)); // None assigned initially
    }

