1. using Xunit;
2. using ContosoUniversity.Services;
3. using ContosoUniversity.Models;
4. 
5. namespace ContosoUniversity.Tests.Services;
6. 
7. public class NotificationServiceTests : IDisposable
8. {
9.     private readonly NotificationService _sut;
10. 
11.     public NotificationServiceTests()
12.     {
13.         _sut = new NotificationService();
14.         // Drain any leftover notifications from the static queue (shared across tests)
15.         while (_sut.ReceiveNotification() != null) { }
16.     }
17. 
18.     public void Dispose()
19.     {
20.         _sut.Dispose();
21.     }
22. 
23.     [Fact]
24.     public void SendNotification_WithoutDisplayName_EnqueuesNotification()
25.     {
26.         // Act
27.         _sut.SendNotification("Student", "42", EntityOperation.CREATE);
28. 
29.         // Assert
30.         var notification = _sut.ReceiveNotification();
31.         Assert.NotNull(notification);
32.         Assert.Equal("Student", notification.EntityType);
33.         Assert.Equal("42", notification.EntityId);
34.         Assert.Equal("CREATE", notification.Operation);
35.         Assert.Contains("Student (ID: 42)", notification.Message);
36.         Assert.Contains("created", notification.Message);
37.         Assert.Equal("System", notification.CreatedBy);
38.         Assert.False(notification.IsRead);
39.     }
40. 
41.     [Fact]
42.     public void SendNotification_WithDisplayName_IncludesDisplayNameInMessage()
43.     {
44.         // Act
45.         _sut.SendNotification("Course", "101", "Advanced Math", EntityOperation.CREATE);
46. 
47.         // Assert
48.         var notification = _sut.ReceiveNotification();
49.         Assert.NotNull(notification);
50.         Assert.Contains("Course 'Advanced Math'", notification.Message);
51.         Assert.Contains("created", notification.Message);
52.     }
53. 
54.     [Fact]
55.     public void SendNotification_WithUserName_SetsCreatedBy()
56.     {
57.         // Act
58.         _sut.SendNotification("Student", "1", EntityOperation.CREATE, "AdminUser");
59. 
60.         // Assert
61.         var notification = _sut.ReceiveNotification();
62.         Assert.NotNull(notification);
63.         Assert.Equal("AdminUser", notification.CreatedBy);
64.     }
65. 
66.     [Fact]
67.     public void SendNotification_WithoutUserName_DefaultsToSystem()
68.     {
69.         // Act
70.         _sut.SendNotification("Student", "1", EntityOperation.UPDATE);
71. 
72.         // Assert
73.         var notification = _sut.ReceiveNotification();
74.         Assert.NotNull(notification);
75.         Assert.Equal("System", notification.CreatedBy);
76.     }
77. 
78.     [Theory]
79.     [InlineData(EntityOperation.CREATE, "created")]
80.     [InlineData(EntityOperation.UPDATE, "updated")]
81.     [InlineData(EntityOperation.DELETE, "deleted")]
82.     public void SendNotification_DifferentOperations_GeneratesCorrectMessage(
83.         EntityOperation operation, string expectedVerb)
84.     {
85.         // Act
86.         _sut.SendNotification("Department", "5", "Engineering", operation);
87. 
88.         // Assert
89.         var notification = _sut.ReceiveNotification();
90.         Assert.NotNull(notification);
91.         Assert.Equal(operation.ToString(), notification.Operation);
92.         Assert.Contains(expectedVerb, notification.Message);
93.         Assert.Contains("Engineering", notification.Message);
94.     }
95. 
96.     [Fact]
97.     public void SendNotification_SetsCreatedAtToNonDefault()
98.     {
99.         // Act
100.         var before = DateTime.Now.AddSeconds(-1);
101.         _sut.SendNotification("Student", "1", EntityOperation.CREATE);
102.         var after = DateTime.Now.AddSeconds(1);
103. 
104.         // Assert
105.         var notification = _sut.ReceiveNotification();
106.         Assert.NotNull(notification);
107.         Assert.InRange(notification.CreatedAt, before, after);
108.     }
109. 
110.     [Fact]
111.     public void ReceiveNotification_WhenQueueEmpty_ReturnsNull()
112.     {
113.         // Act
114.         var result = _sut.ReceiveNotification();
115. 
116.         // Assert
117.         Assert.Null(result);
118.     }
119. 
120.     [Fact]
121.     public void ReceiveNotification_ReturnsFIFOOrder()
122.     {
